using System;
using System.Collections.Generic;
using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CharacterRunes", menuName = "Data/Characters/Runes")]
public class CharacterRunes : ScriptableObject
{
	[Serializable]
	public class VirtueSetInfo
	{
		public string SetId;

		public Rune[] Runes;
	}

	[Serializable]
	public class ModVirtueInfo
	{
		public string PublishedId;

		public List<VirtueSetInfo> VirtuesSetInfosList;

		public ModVirtueInfo(string publishedId)
		{
			PublishedId = publishedId;
			VirtuesSetInfosList = new List<VirtueSetInfo>();
		}
	}

	[Header("Default Runes")]
	public Rune[] DefaultRunes = new Rune[0];

	[Header("Custom Runes")]
	public List<ModVirtueInfo> CustomRunesList = new List<ModVirtueInfo>();

	[Header("Editor: Build Runes")]
	[HorizontalLine(2f, EColor.Gray)]
	public Rune[] BuildRunes = new Rune[0];
}
